		lineStart := p.pos
		p.skipBlank()

		if p.atLineEnd() {
			p.consumeLineEnd()

			continue
		}

		if p.data[p.pos] == '#' || p.data[p.pos] == ';' {
			p.skipToLineEnd()
			p.consumeLineEnd()

			continue
		}

		sawHeader := false

		if p.data[p.pos] == '[' {
			if err := p.parseHeader(lineStart); err != nil {
				return err
			}

			sawHeader = true

			p.skipBlank()

			if p.atLineEnd() || p.data[p.pos] == '#' || p.data[p.pos] == ';' {
				p.curSec.plain = p.atLineEnd()
