	"github.com/go-git/go-git/v6/plumbing/client"
	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/plumbing/transport/ssh"
	"github.com/go-git/go-git/v6/utils/trace"
	"github.com/spf13/cobra"
	gossh "golang.org/x/crypto/ssh"
)

var rootCmd = &cobra.Command{
	Use:     "gogit [<args>] <command>",
	Short:   "gogit is a Git CLI that uses go-git as its backend.",
	Version: "0.1.0-gogit",
	RunE: func(_ *cobra.Command, _ []string) error {
		// Real git exits 1 when invoked with no subcommand. test-lib.sh
		// relies on this to detect a working git binary. We deliberately
		// omit printing usage so summary-mode harness output stays clean
		// during test-lib's sanity checks.
		os.Exit(1)

		return nil
	},
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

// envToTarget maps what environment variables can be used
// to enable specific trace targets.
var envToTarget = map[string]trace.Target{
	"GIT_TRACE":             trace.General,
	"GIT_TRACE_PACKET":      trace.Packet,
	"GIT_TRACE_SSH":         trace.SSH,
	"GIT_TRACE_PERFORMANCE": trace.Performance,
}

func init() {
	// Set up tracing
	var target trace.Target

	for k, v := range envToTarget {
		if ok, _ := strconv.ParseBool(os.Getenv(k)); ok {
			target |= v
		}
	}

	trace.SetTarget(target)
}

func init() {
	rootCmd.PersistentFlags().StringArrayVarP(&configOverridesRaw, "config", "c", nil,
		"Override a configuration value for the duration of this command (key=value, may be repeated)")
	rootCmd.PersistentPreRunE = func(_ *cobra.Command, _ []string) error {
		return applyConfigOverridesFromFlags()
	}
}

func main() {
	for _, arg := range os.Args[1:] {
		if arg == "--exec-path" || strings.HasPrefix(arg, "--exec-path=") {
			exe, err := os.Executable()
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}

			fmt.Println(filepath.Dir(exe))

			return
		}
	}

	err := rootCmd.Execute()
	if err != nil {
		// Some commands need git's own exit statuses, and git stays
		// silent for several of them, so gitExitError carries both the
		// code and whether anything is printed.
		var gerr *gitExitError
		if errors.As(err, &gerr) {
			if gerr.msg != "" {
				fmt.Fprintln(os.Stderr, gerr.msg)
			}

			os.Exit(gerr.code)
		}

		var rerr *transport.RemoteError
		if errors.As(err, &rerr) {
			fmt.Fprintln(os.Stderr, rerr)
		} else {
			fmt.Fprintln(os.Stderr, err)
		}

		os.Exit(1)
	}
}

func defaultClientOptions(u *url.URL) []client.Option {
	if u == nil {
		return nil
	}

	switch u.Scheme {
	case "file", "git":
		// Do nothing.
	case "ssh":
		if u.User == nil {
			return nil
		}

		if processed[idx] {
			continue
		}

		var group []int

		for candidate, s := range f.sections {
			if s.key.sameSection(f.sections[idx].key) {
				group = append(group, candidate)
				processed[candidate] = true
			}
		}

		if groupHasRemainingOption(f.options, group, deletions) ||
			groupHasContent(f.data, f.sections, group, deletions) {
			continue
		}

		allPlain := true

		for _, candidate := range group {
			if !f.sectionPlainAfterDeletions(candidate, deletions) {
				allPlain = false

				break
			}
		}

		if !allPlain {
			continue
		}

		for _, candidate := range group {
			s := f.sections[candidate]
			out = append(out, edit{start: s.lineStart, end: s.lineEnd})
		}
	}

	return out
}

func (f *File) sectionPlainAfterDeletions(section int, deletions []edit) bool {
	if f.sections[section].plain {
		return true
	}

	for _, o := range f.options {
		if o.secIdx == section && !o.alone {
			return isDeletedOption(o, deletions)
		}
	}

	return false
}

func isDeletedOption(o *optionRec, deletions []edit) bool {
	nameStart := o.nameEnd - len(o.key.Name)

	for _, d := range deletions {
		if nameStart >= d.start && o.logicalEnd <= d.end {
			return true
		}
	}

	return false
}

func groupHasRemainingOption(options []*optionRec, group []int, deletions []edit) bool {
	for _, o := range options {
		for _, idx := range group {
			if o.secIdx == idx && !isDeletedOption(o, deletions) {
				return true
			}
		}
	}

	return false
}

func groupHasContent(data []byte, sections []*sectionRec, group []int, deletions []edit) bool {
	for _, idx := range group {
		s := sections[idx]
		for i := s.lineEnd; i < s.regionEnd && i < len(data); i++ {
			deleted := false

			for _, d := range deletions {
				if i >= d.start && i < d.end {
					deleted = true

					break
				}
			}

			if !deleted && !isSpace(data[i]) {
				return true
			}
		}
	}

	return false
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\r' || c == '\n'
}

func (f *File) rewrite(o *optionRec, key Key, value string) error {
	return f.apply([]edit{f.writeEdit(o, key, value)})
}

